  1→package checkpoint
  2→
  3→import (
  4→	"fmt"
  5→	"strings"
  6→
  7→	"github.com/entireio/cli/cmd/entire/cli/paths"
  8→
  9→	"github.com/go-git/go-git/v5"
 10→	"github.com/go-git/go-git/v5/plumbing"
 11→	"github.com/go-git/go-git/v5/plumbing/filemode"
 12→	"github.com/go-git/go-git/v5/plumbing/object"
 13→)
 14→
 15→// TreeChange represents a single file change within a tree.
 16→// Use a nil Entry to indicate deletion.
 17→type TreeChange struct {
 18→	// Path is the full path within the tree (e.g., "src/pkg/handler.go").
 19→	Path string
 20→	// Entry is the new tree entry. Nil means delete the file at Path.
 21→	Entry *object.TreeEntry
 22→}
 23→
 24→// MergeMode controls how entries at the leaf directory are handled by UpdateSubtree.
 25→type MergeMode int
 26→
 27→const (
 28→	// ReplaceAll replaces the entire leaf directory contents with the new entries.
 29→	ReplaceAll MergeMode = iota
 30→	// MergeKeepExisting merges new entries into the existing leaf directory,
 31→	// keeping existing entries that are not overwritten (unless in DeleteNames).
 32→	MergeKeepExisting
 33→)
 34→
 35→// UpdateSubtreeOptions configures the behavior of UpdateSubtree.
 36→type UpdateSubtreeOptions struct {
 37→	// MergeMode controls how entries at the leaf directory are handled.
 38→	MergeMode MergeMode
 39→	// DeleteNames lists entry names (at the leaf directory level) to delete.
 40→	// Only applicable when MergeMode is MergeKeepExisting.
 41→	DeleteNames []string
 42→}
 43→
 44→// UpdateSubtree replaces or creates a subtree at the given path within an existing tree.
 45→// It walks the tree path, replacing only the entries along the modified path.
 46→// All sibling entries at each level retain their original hashes — no re-reading needed.
 47→//
 48→// pathSegments is the directory path split into segments (e.g., ["a3", "b2c4d5e6f7"]).
 49→// newEntries are the files/dirs to place at the leaf directory.
 50→// Returns the new root tree hash.
 51→func UpdateSubtree(
 52→	repo *git.Repository,
 53→	rootTreeHash plumbing.Hash,
 54→	pathSegments []string,
 55→	newEntries []object.TreeEntry,
 56→	opts UpdateSubtreeOptions,
 57→) (plumbing.Hash, error) {
 58→	if len(pathSegments) == 0 {
 59→		return buildLeafTree(repo, rootTreeHash, newEntries, opts)
 60→	}
 61→
 62→	// Read the current tree at this level
 63→	var currentEntries []object.TreeEntry
 64→	if rootTreeHash != plumbing.ZeroHash {
 65→		tree, err := repo.TreeObject(rootTreeHash)
 66→		if err != nil {
 67→			return plumbing.ZeroHash, fmt.Errorf("failed to read tree %s: %w", rootTreeHash, err)
 68→		}
 69→		currentEntries = tree.Entries
 70→	}
 71→
 72→	targetDir := pathSegments[0]
 73→	remainingPath := pathSegments[1:]
 74→
 75→	// Find the existing subtree entry for targetDir
 76→	var existingSubtreeHash plumbing.Hash
 77→	found := false
 78→	for _, entry := range currentEntries {
 79→		if entry.Name == targetDir && entry.Mode == filemode.Dir {
 80→			existingSubtreeHash = entry.Hash
 81→			found = true
 82→			break
 83→		}
 84→	}
 85→
 86→	// Recurse into the subtree
 87→	newSubtreeHash, err := UpdateSubtree(repo, existingSubtreeHash, remainingPath, newEntries, opts)
 88→	if err != nil {
 89→		return plumbing.ZeroHash, err
 90→	}
 91→
 92→	// Build a new tree at this level with the updated subtree entry
 93→	updatedEntries := make([]object.TreeEntry, 0, len(currentEntries)+1)
 94→	replaced := false
 95→	for _, entry := range currentEntries {
 96→		if entry.Name == targetDir {
 97→			updatedEntries = append(updatedEntries, object.TreeEntry{
 98→				Name: targetDir,
 99→				Mode: filemode.Dir,
100→				Hash: newSubtreeHash,
101→			})
102→			replaced = true
103→		} else {
104→			updatedEntries = append(updatedEntries, entry)
105→		}
106→	}
107→	if !found && !replaced {
108→		updatedEntries = append(updatedEntries, object.TreeEntry{
109→			Name: targetDir,
110→			Mode: filemode.Dir,
111→			Hash: newSubtreeHash,
112→		})
113→	}
114→
115→	sortTreeEntries(updatedEntries)
116→	return storeTree(repo, updatedEntries)
117→}
118→
119→// buildLeafTree builds the tree at the leaf of the UpdateSubtree path.
120→func buildLeafTree(
121→	repo *git.Repository,
122→	existingTreeHash plumbing.Hash,
123→	newEntries []object.TreeEntry,
124→	opts UpdateSubtreeOptions,
125→) (plumbing.Hash, error) {
126→	if opts.MergeMode == ReplaceAll || existingTreeHash == plumbing.ZeroHash {
127→		sorted := make([]object.TreeEntry, len(newEntries))
128→		copy(sorted, newEntries)
129→		sortTreeEntries(sorted)
130→		return storeTree(repo, sorted)
131→	}
132→
133→	// MergeKeepExisting: read existing tree, merge
134→	existingTree, err := repo.TreeObject(existingTreeHash)
135→	if err != nil {
136→		sorted := make([]object.TreeEntry, len(newEntries))
137→		copy(sorted, newEntries)
138→		sortTreeEntries(sorted)
139→		return storeTree(repo, sorted)
140→	}
141→
142→	// Build lookup of new entries by name
143→	newByName := make(map[string]object.TreeEntry, len(newEntries))
144→	for _, e := range newEntries {
145→		newByName[e.Name] = e
146→	}
147→
148→	// Build delete set
149→	deleteSet := make(map[string]bool, len(opts.DeleteNames))
150→	for _, name := range opts.DeleteNames {
151→		deleteSet[name] = true
152→	}
153→
154→	// Merge: keep existing unless overwritten or deleted
155→	merged := make([]object.TreeEntry, 0, len(existingTree.Entries)+len(newEntries))
156→	for _, existing := range existingTree.Entries {
157→		if deleteSet[existing.Name] {
158→			continue
159→		}
160→		if replacement, ok := newByName[existing.Name]; ok {
161→			merged = append(merged, replacement)
162→			delete(newByName, existing.Name)
163→		} else {
164→			merged = append(merged, existing)
165→		}
166→	}
167→	// Add remaining new entries (ones that didn't replace an existing entry)
168→	for _, e := range newEntries {
169→		if _, stillNew := newByName[e.Name]; stillNew {
170→			merged = append(merged, e)
171→		}
172→	}
173→
174→	sortTreeEntries(merged)
175→	return storeTree(repo, merged)
176→}
