178→// storeTree creates a git tree object from entries and stores it in the repo.
179→func storeTree(repo *git.Repository, entries []object.TreeEntry) (plumbing.Hash, error) {
180→	tree := &object.Tree{Entries: entries}
181→	obj := repo.Storer.NewEncodedObject()
182→	if err := tree.Encode(obj); err != nil {
183→		return plumbing.ZeroHash, fmt.Errorf("failed to encode tree: %w", err)
184→	}
185→	hash, err := repo.Storer.SetEncodedObject(obj)
186→	if err != nil {
187→		return plumbing.ZeroHash, fmt.Errorf("failed to store tree: %w", err)
188→	}
189→	return hash, nil
190→}
191→
192→// ApplyTreeChanges applies multiple file-level changes to a tree efficiently.
193→// Changes are grouped by directory and applied in a single recursive pass.
194→// Unchanged subdirectories retain their hashes — this is the key optimization
195→// over FlattenTree + BuildTreeFromEntries for sparse changes.
196→func ApplyTreeChanges(
197→	repo *git.Repository,
198→	rootTreeHash plumbing.Hash,
199→	changes []TreeChange,
200→) (plumbing.Hash, error) {
201→	if len(changes) == 0 {
202→		return rootTreeHash, nil
203→	}
204→
205→	// Read the current root tree
206→	var currentEntries []object.TreeEntry
207→	if rootTreeHash != plumbing.ZeroHash {
208→		tree, err := repo.TreeObject(rootTreeHash)
209→		if err != nil {
210→			return plumbing.ZeroHash, fmt.Errorf("failed to read tree: %w", err)
211→		}
212→		currentEntries = make([]object.TreeEntry, len(tree.Entries))
213→		copy(currentEntries, tree.Entries)
214→	}
215→
216→	// Group changes by first path segment
217→	type dirChanges struct {
218→		subChanges []TreeChange // Changes within this subdirectory
219→		fileChange *TreeChange  // Direct file change at this level (nil if none)
220→	}
221→	grouped := make(map[string]*dirChanges)
222→
223→	for i := range changes {
224→		c := changes[i]
225→		first, rest := splitFirstSegment(c.Path)
226→		if grouped[first] == nil {
227→			grouped[first] = &dirChanges{}
228→		}
229→		if rest == "" {
230→			cc := c
231→			grouped[first].fileChange = &cc
232→		} else {
233→			grouped[first].subChanges = append(grouped[first].subChanges, TreeChange{
234→				Path:  rest,
235→				Entry: c.Entry,
236→			})
237→		}
238→	}
239→
240→	// Build entry map for modifications
241→	entryMap := make(map[string]object.TreeEntry, len(currentEntries))
242→	for _, e := range currentEntries {
243→		entryMap[e.Name] = e
244→	}
245→
246→	// Process each group
247→	for name, dc := range grouped {
248→		if dc.fileChange != nil {
249→			if dc.fileChange.Entry == nil {
250→				delete(entryMap, name)
251→			} else {
252→				entryMap[name] = object.TreeEntry{
253→					Name: name,
254→					Mode: dc.fileChange.Entry.Mode,
255→					Hash: dc.fileChange.Entry.Hash,
256→				}
257→			}
258→		}
259→		if len(dc.subChanges) > 0 {
260→			existingHash := plumbing.ZeroHash
261→			if existing, ok := entryMap[name]; ok && existing.Mode == filemode.Dir {
262→				existingHash = existing.Hash
263→			}
264→			newSubHash, err := ApplyTreeChanges(repo, existingHash, dc.subChanges)
265→			if err != nil {
266→				return plumbing.ZeroHash, fmt.Errorf("failed to apply changes in %s: %w", name, err)
267→			}
268→			entryMap[name] = object.TreeEntry{
269→				Name: name,
270→				Mode: filemode.Dir,
271→				Hash: newSubHash,
272→			}
273→		}
274→	}
275→
276→	result := make([]object.TreeEntry, 0, len(entryMap))
277→	for _, e := range entryMap {
278→		result = append(result, e)
279→	}
280→	sortTreeEntries(result)
281→	return storeTree(repo, result)
282→}
283→
284→// splitFirstSegment splits "a/b/c" into ("a", "b/c"), and "file.txt" into ("file.txt", "").
285→func splitFirstSegment(path string) (first, rest string) {
286→	parts := strings.SplitN(path, "/", 2)
287→	if len(parts) == 1 {
288→		return parts[0], ""
289→	}
290→	return parts[0], parts[1]
291→}
