293→// getSessionsBranchRef returns the sessions branch parent commit hash and root tree hash
294→// without flattening the tree. This is the O(1) replacement for getSessionsBranchEntries.
295→func (s *GitStore) getSessionsBranchRef() (plumbing.Hash, plumbing.Hash, error) {
296→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
297→	ref, err := s.repo.Reference(refName, true)
298→	if err != nil {
299→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get sessions branch reference: %w", err)
300→	}
301→
302→	parentCommit, err := s.repo.CommitObject(ref.Hash())
303→	if err != nil {
304→		return plumbing.ZeroHash, plumbing.ZeroHash, fmt.Errorf("failed to get commit object: %w", err)
305→	}
306→
307→	return ref.Hash(), parentCommit.TreeHash, nil
308→}
