 35→// flattenTreeHelper reads a tree recursively and returns all entries as path->hash.
 36→func flattenTreeHelper(t *testing.T, repo *git.Repository, treeHash plumbing.Hash, prefix string) map[string]plumbing.Hash {
 37→	t.Helper()
 38→	result := make(map[string]plumbing.Hash)
 39→	tree, err := repo.TreeObject(treeHash)
 40→	if err != nil {
 41→		t.Fatalf("failed to read tree %s: %v", treeHash, err)
 42→	}
 43→	for _, entry := range tree.Entries {
 44→		fullPath := entry.Name
 45→		if prefix != "" {
 46→			fullPath = prefix + "/" + entry.Name
 47→		}
 48→		if entry.Mode == filemode.Dir {
 49→			sub := flattenTreeHelper(t, repo, entry.Hash, fullPath)
 50→			for k, v := range sub {
 51→				result[k] = v
 52→			}
 53→		} else {
 54→			result[fullPath] = entry.Hash
 55→		}
 56→	}
 57→	return result
 58→}
