 13→// storeBlob is a test helper that stores a blob in the repo and returns its hash.
 14→func storeBlob(t *testing.T, repo *git.Repository, content string) plumbing.Hash {
 15→	t.Helper()
 16→	obj := repo.Storer.NewEncodedObject()
 17→	obj.SetType(plumbing.BlobObject)
 18→	w, err := obj.Writer()
 19→	if err != nil {
 20→		t.Fatalf("failed to get blob writer: %v", err)
 21→	}
 22→	if _, err := w.Write([]byte(content)); err != nil {
 23→		t.Fatalf("failed to write blob content: %v", err)
 24→	}
 25→	if err := w.Close(); err != nil {
 26→		t.Fatalf("failed to close blob writer: %v", err)
 27→	}
 28→	hash, err := repo.Storer.SetEncodedObject(obj)
 29→	if err != nil {
 30→		t.Fatalf("failed to store blob: %v", err)
 31→	}
 32→	return hash
 33→}
