  39→// WriteCommitted writes a committed checkpoint to the entire/checkpoints/v1 branch.
  40→// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
  41→//
  42→// For task checkpoints (IsTask=true), additional files are written under tasks/<tool-use-id>/:
  43→//   - For incremental checkpoints: checkpoints/NNN-<tool-use-id>.json
  44→//   - For final checkpoints: checkpoint.json and agent-<agent-id>.jsonl
  45→func (s *GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
  46→	_ = ctx // Reserved for future use
  47→
  48→	// Validate identifiers to prevent path traversal and malformed data
  49→	if opts.CheckpointID.IsEmpty() {
  50→		return errors.New("invalid checkpoint options: checkpoint ID is required")
  51→	}
  52→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
  53→		return fmt.Errorf("invalid checkpoint options: %w", err)
  54→	}
  55→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
  56→		return fmt.Errorf("invalid checkpoint options: %w", err)
  57→	}
  58→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
  59→		return fmt.Errorf("invalid checkpoint options: %w", err)
  60→	}
  61→
  62→	// Ensure sessions branch exists
  63→	if err := s.ensureSessionsBranch(); err != nil {
  64→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
  65→	}
  66→
  67→	// Get branch ref and root tree hash (O(1), no flatten)
  68→	parentHash, rootTreeHash, err := s.getSessionsBranchRef()
  69→	if err != nil {
  70→		return err
  71→	}
  72→
  73→	// Use sharded path: <id[:2]>/<id[2:]>/
  74→	basePath := opts.CheckpointID.Path() + "/"
  75→	checkpointPath := opts.CheckpointID.Path()
  76→
  77→	// Flatten only the checkpoint subtree (O(files in checkpoint))
  78→	entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
  79→	if err != nil {
  80→		return err
  81→	}
  82→
  83→	// Track task metadata path for commit trailer
  84→	var taskMetadataPath string
  85→
  86→	// Handle task checkpoints
  87→	if opts.IsTask && opts.ToolUseID != "" {
  88→		taskMetadataPath, err = s.writeTaskCheckpointEntries(opts, basePath, entries)
  89→		if err != nil {
  90→			return err
  91→		}
  92→	}
  93→
  94→	// Write standard checkpoint entries (transcript, prompts, context, metadata)
  95→	if err := s.writeStandardCheckpointEntries(opts, basePath, entries); err != nil {
  96→		return err
  97→	}
  98→
  99→	// Build checkpoint subtree and splice into root (O(depth) tree surgery)
 100→	newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
 101→	if err != nil {
 102→		return err
 103→	}
 104→
 105→	commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
 106→	newCommitHash, err := s.createCommit(newTreeHash, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
 107→	if err != nil {
 108→		return err
 109→	}
 110→
 111→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
 112→	newRef := plumbing.NewHashReference(refName, newCommitHash)
 113→	if err := s.repo.Storer.SetReference(newRef); err != nil {
 114→		return fmt.Errorf("failed to set branch reference: %w", err)
 115→	}
 116→
 117→	return nil
 118→}
