 176→// writeTaskCheckpointEntries writes task-specific checkpoint entries and returns the task metadata path.
 177→func (s *GitStore) writeTaskCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (string, error) {
 178→	taskPath := basePath + "tasks/" + opts.ToolUseID + "/"
 179→
 180→	if opts.IsIncremental {
