 186→// writeIncrementalTaskCheckpoint writes an incremental checkpoint file during task execution.
 187→func (s *GitStore) writeIncrementalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
 188→	incData, err := redact.JSONLBytes(opts.IncrementalData)
 189→	if err != nil {
 190→		return "", fmt.Errorf("failed to redact incremental checkpoint: %w", err)
 191→	}
 192→	checkpoint := incrementalCheckpointData{
 193→		Type:      opts.IncrementalType,
 194→		ToolUseID: opts.ToolUseID,
 195→		Timestamp: time.Now().UTC(),
 196→		Data:      incData,
 197→	}
 198→	cpData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
 199→	if err != nil {
 200→		return "", fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
 201→	}
 202→	cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
 203→	if err != nil {
 204→		return "", fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
 205→	}
 206→
 207→	cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
 208→	cpPath := taskPath + "checkpoints/" + cpFilename
 209→	entries[cpPath] = object.TreeEntry{
 210→		Name: cpPath,
 211→		Mode: filemode.Regular,
 212→		Hash: cpBlobHash,
 213→	}
 214→	return cpPath, nil
 215→}
