 419→// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
 420→// sessions is the complete sessions array (already built by the caller).
 421→func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, sessions []SessionFilePaths) error {
 422→	checkpointsCount, filesTouched, tokenUsage, err :=
 423→		s.reaggregateFromEntries(basePath, len(sessions), entries)
 424→	if err != nil {
 425→		return fmt.Errorf("failed to aggregate session stats: %w", err)
 426→	}
 427→
 428→	summary := CheckpointSummary{
 429→		CheckpointID:     opts.CheckpointID,
 430→		CLIVersion:       buildinfo.Version,
 431→		Strategy:         opts.Strategy,
 432→		Branch:           opts.Branch,
 433→		CheckpointsCount: checkpointsCount,
 434→		FilesTouched:     filesTouched,
 435→		Sessions:         sessions,
 436→		TokenUsage:       tokenUsage,
 437→	}
 438→
 439→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
 440→	if err != nil {
 441→		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
 442→	}
 443→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
 444→	if err != nil {
 445→		return err
 446→	}
 447→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
 448→		Name: basePath + paths.MetadataFileName,
 449→		Mode: filemode.Regular,
 450→		Hash: metadataHash,
 451→	}
 452→	return nil
 453→}
 454→
 455→// findSessionIndex returns the index of an existing session with the given ID,
 456→// or the next available index if not found. This prevents duplicate session entries.
 457→func (s *GitStore) findSessionIndex(basePath string, existingSummary *CheckpointSummary, entries map[string]object.TreeEntry, sessionID string) int {
 458→	if existingSummary == nil {
 459→		return 0
 460→	}
 461→	for i := range len(existingSummary.Sessions) {
 462→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
 463→		if entry, exists := entries[path]; exists {
 464→			meta, err := s.readMetadataFromBlob(entry.Hash)
 465→			if err != nil {
 466→				logging.Warn(context.Background(), "failed to read session metadata during dedup check",
 467→					slog.Int("session_index", i),
 468→					slog.String("session_id", sessionID),
 469→					slog.String("error", err.Error()),
 470→				)
 471→				continue
 472→			}
 473→			if meta.SessionID == sessionID {
 474→				return i
 475→			}
 476→		}
 477→	}
 478→	return len(existingSummary.Sessions)
 479→}
 480→
 481→// reaggregateFromEntries reads all session metadata from the entries map and
 482→// reaggregates CheckpointsCount, FilesTouched, and TokenUsage.
 483→func (s *GitStore) reaggregateFromEntries(basePath string, sessionCount int, entries map[string]object.TreeEntry) (int, []string, *agent.TokenUsage, error) {
 484→	var totalCount int
 485→	var allFiles []string
 486→	var totalTokens *agent.TokenUsage
 487→
 488→	for i := range sessionCount {
 489→		path := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
 490→		entry, exists := entries[path]
 491→		if !exists {
 492→			return 0, nil, nil, fmt.Errorf("session %d metadata not found at %s", i, path)
 493→		}
 494→		meta, err := s.readMetadataFromBlob(entry.Hash)
 495→		if err != nil {
 496→			return 0, nil, nil, fmt.Errorf("failed to read session %d metadata: %w", i, err)
 497→		}
 498→		totalCount += meta.CheckpointsCount
 499→		allFiles = mergeFilesTouched(allFiles, meta.FilesTouched)
 500→		totalTokens = aggregateTokenUsage(totalTokens, meta.TokenUsage)
 501→	}
 502→
 503→	return totalCount, allFiles, totalTokens, nil
 504→}
 505→
 506→// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
 507→func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
 508→	blob, err := repo.BlobObject(hash)
 509→	if err != nil {
 510→		return nil, fmt.Errorf("failed to get blob: %w", err)
 511→	}
 512→
 513→	reader, err := blob.Reader()
 514→	if err != nil {
 515→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
 516→	}
 517→	defer reader.Close()
 518→
 519→	var result T
 520→	if err := json.NewDecoder(reader).Decode(&result); err != nil {
 521→		return nil, fmt.Errorf("failed to decode: %w", err)
 522→	}
 523→
 524→	return &result, nil
 525→}
