 527→// readSummaryFromBlob reads CheckpointSummary from a blob hash.
 528→func (s *GitStore) readSummaryFromBlob(hash plumbing.Hash) (*CheckpointSummary, error) {
 529→	return readJSONFromBlob[CheckpointSummary](s.repo, hash)
 530→}
