 556→// writeTranscript writes the transcript file from in-memory content or file path.
 557→// If the transcript exceeds MaxChunkSize, it's split into multiple chunk files.
 558→func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
 559→	transcript := opts.Transcript
 560→	if len(transcript) == 0 && opts.TranscriptPath != "" {
 561→		var readErr error
 562→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
 563→		if readErr != nil {
 564→			// Non-fatal: transcript may not exist yet
 565→			transcript = nil
 566→		}
 567→	}
 568→	if len(transcript) == 0 {
 569→		return nil
 570→	}
 571→
 572→	// Redact secrets before chunking so content hash reflects redacted content
 573→	transcript, err := redact.JSONLBytes(transcript)
 574→	if err != nil {
 575→		return fmt.Errorf("failed to redact transcript secrets: %w", err)
 576→	}
 577→
 578→	// Chunk the transcript if it's too large
 579→	chunks, err := agent.ChunkTranscript(transcript, opts.Agent)
 580→	if err != nil {
 581→		return fmt.Errorf("failed to chunk transcript: %w", err)
 582→	}
 583→
 584→	// Write chunk files
 585→	for i, chunk := range chunks {
 586→		chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
 587→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
 588→		if err != nil {
 589→			return err
 590→		}
 591→		entries[chunkPath] = object.TreeEntry{
 592→			Name: chunkPath,
 593→			Mode: filemode.Regular,
 594→			Hash: blobHash,
 595→		}
 596→	}
 597→
 598→	// Content hash for deduplication (hash of full transcript)
 599→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
 600→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
 601→	if err != nil {
 602→		return err
 603→	}
 604→	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
 605→		Name: basePath + paths.ContentHashFileName,
 606→		Mode: filemode.Regular,
 607→		Hash: hashBlob,
 608→	}
 609→	return nil
 610→}
 611→
 612→// mergeFilesTouched combines two file lists, removing duplicates.
 613→func mergeFilesTouched(existing, additional []string) []string {
 614→	seen := make(map[string]bool)
 615→	var result []string
 616→
 617→	for _, f := range existing {
 618→		if !seen[f] {
 619→			seen[f] = true
 620→			result = append(result, f)
 621→		}
 622→	}
 623→	for _, f := range additional {
 624→		if !seen[f] {
 625→			seen[f] = true
 626→			result = append(result, f)
 627→		}
 628→	}
 629→
 630→	sort.Strings(result)
 631→	return result
 632→}
