 684→// readMetadataFromBlob reads CommittedMetadata from a blob hash.
 685→func (s *GitStore) readMetadataFromBlob(hash plumbing.Hash) (*CommittedMetadata, error) {
 686→	return readJSONFromBlob[CommittedMetadata](s.repo, hash)
