 734→
 735→// ReadCommitted reads a committed checkpoint's summary by ID from the entire/checkpoints/v1 branch.
 736→// Returns only the CheckpointSummary (paths + aggregated stats), not actual content.
 737→// Use ReadSessionContent to read actual transcript/prompts/context.
 738→// Returns nil, nil if the checkpoint doesn't exist.
 739→//
 740→// The storage format uses numbered subdirectories for each session (0-based):
 741→//
 742→//	<checkpoint-id>/
 743→//	├── metadata.json      # CheckpointSummary with sessions map
 744→//	├── 0/                 # First session
 745→//	│   ├── metadata.json  # Session-specific metadata
 746→//	│   └── full.jsonl     # Transcript
 747→//	├── 1/                 # Second session
 748→//	└── ...
 749→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*CheckpointSummary, error) {
 750→	_ = ctx // Reserved for future use
 751→
 752→	tree, err := s.getSessionsBranchTree()
 753→	if err != nil {
 754→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
 755→	}
 756→
 757→	checkpointPath := checkpointID.Path()
 758→	checkpointTree, err := tree.Tree(checkpointPath)
 759→	if err != nil {
 760→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
 761→	}
 762→
 763→	// Read root metadata.json as CheckpointSummary
 764→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
 765→	if err != nil {
 766→		return nil, nil //nolint:nilnil,nilerr // metadata.json not found
 767→	}
 768→
 769→	content, err := metadataFile.Contents()
 770→	if err != nil {
 771→		return nil, fmt.Errorf("failed to read metadata.json: %w", err)
 772→	}
 773→
 774→	var summary CheckpointSummary
 775→	if err := json.Unmarshal([]byte(content), &summary); err != nil {
 776→		return nil, fmt.Errorf("failed to parse metadata.json: %w", err)
 777→	}
 778→
 779→	return &summary, nil
 780→}
 781→
 782→// ReadSessionContent reads the actual content for a specific session within a checkpoint.
 783→// sessionIndex is 0-based (0 for first session, 1 for second, etc.).
 784→// Returns the session's metadata, transcript, prompts, and context.
 785→// Returns an error if the checkpoint or session doesn't exist.
 786→func (s *GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
 787→	_ = ctx // Reserved for future use
 788→
 789→	tree, err := s.getSessionsBranchTree()
 790→	if err != nil {
 791→		return nil, ErrCheckpointNotFound
 792→	}
 793→
 794→	checkpointPath := checkpointID.Path()
 795→	checkpointTree, err := tree.Tree(checkpointPath)
 796→	if err != nil {
 797→		return nil, ErrCheckpointNotFound
 798→	}
 799→
 800→	// Get the session subdirectory
 801→	sessionDir := strconv.Itoa(sessionIndex)
 802→	sessionTree, err := checkpointTree.Tree(sessionDir)
 803→	if err != nil {
 804→		return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
 805→	}
 806→
 807→	result := &SessionContent{}
 808→
 809→	// Read session-specific metadata
 810→	var agentType agent.AgentType
 811→	if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
 812→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
 813→			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr == nil {
 814→				agentType = result.Metadata.Agent
 815→			}
 816→		}
 817→	}
 818→
 819→	// Read transcript
 820→	if transcript, transcriptErr := readTranscriptFromTree(sessionTree, agentType); transcriptErr == nil && transcript != nil {
 821→		result.Transcript = transcript
 822→	}
 823→
 824→	// Read prompts
 825→	if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
 826→		if content, contentErr := file.Contents(); contentErr == nil {
 827→			result.Prompts = content
 828→		}
 829→	}
 830→
 831→	// Read context
 832→	if file, fileErr := sessionTree.File(paths.ContextFileName); fileErr == nil {
 833→		if content, contentErr := file.Contents(); contentErr == nil {
 834→			result.Context = content
 835→		}
 836→	}
