1025→// UpdateSummary updates the summary field in the latest session's metadata.
1026→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
1027→func (s *GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
1028→	_ = ctx // Reserved for future use
1029→
1030→	// Ensure sessions branch exists
1031→	if err := s.ensureSessionsBranch(); err != nil {
1032→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
1033→	}
1034→
1035→	// Get branch ref and root tree hash (O(1), no flatten)
1036→	parentHash, rootTreeHash, err := s.getSessionsBranchRef()
1037→	if err != nil {
1038→		return err
1039→	}
1040→
1041→	// Flatten only the checkpoint subtree
1042→	basePath := checkpointID.Path() + "/"
1043→	checkpointPath := checkpointID.Path()
1044→	entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
1045→	if err != nil {
1046→		return err
1047→	}
1048→
1049→	// Read root CheckpointSummary to find the latest session
1050→	rootMetadataPath := basePath + paths.MetadataFileName
1051→	entry, exists := entries[rootMetadataPath]
1052→	if !exists {
1053→		return ErrCheckpointNotFound
1054→	}
1055→
1056→	checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
1057→	if err != nil {
1058→		return fmt.Errorf("failed to read checkpoint summary: %w", err)
1059→	}
1060→
1061→	// Find the latest session's metadata path (0-based indexing)
1062→	latestIndex := len(checkpointSummary.Sessions) - 1
1063→	sessionMetadataPath := fmt.Sprintf("%s%d/%s", basePath, latestIndex, paths.MetadataFileName)
1064→	sessionEntry, exists := entries[sessionMetadataPath]
1065→	if !exists {
1066→		return fmt.Errorf("session metadata not found at %s", sessionMetadataPath)
1067→	}
1068→
1069→	// Read and update session metadata
1070→	existingMetadata, err := s.readMetadataFromBlob(sessionEntry.Hash)
1071→	if err != nil {
1072→		return fmt.Errorf("failed to read session metadata: %w", err)
1073→	}
1074→
1075→	// Update the summary
1076→	existingMetadata.Summary = redactSummary(summary)
1077→
1078→	// Write updated session metadata
1079→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(existingMetadata, "", "  ")
1080→	if err != nil {
1081→		return fmt.Errorf("failed to marshal metadata: %w", err)
1082→	}
1083→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
1084→	if err != nil {
1085→		return fmt.Errorf("failed to create metadata blob: %w", err)
1086→	}
1087→	entries[sessionMetadataPath] = object.TreeEntry{
1088→		Name: sessionMetadataPath,
1089→		Mode: filemode.Regular,
1090→		Hash: metadataHash,
1091→	}
1092→
1093→	// Build checkpoint subtree and splice into root (O(depth) tree surgery)
1094→	newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, checkpointID, basePath, entries)
1095→	if err != nil {
1096→		return err
1097→	}
1098→
1099→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
1100→	commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, existingMetadata.SessionID)
1101→	newCommitHash, err := s.createCommit(newTreeHash, parentHash, commitMsg, authorName, authorEmail)
1102→	if err != nil {
1103→		return err
1104→	}
1105→
1106→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1107→	newRef := plumbing.NewHashReference(refName, newCommitHash)
1108→	if err := s.repo.Storer.SetReference(newRef); err != nil {
1109→		return fmt.Errorf("failed to set branch reference: %w", err)
1110→	}
1111→
1112→	return nil
1113→}
