1321→// getSessionsBranchTree returns the tree object for the entire/checkpoints/v1 branch.
1322→// Falls back to origin/entire/checkpoints/v1 if the local branch doesn't exist.
1323→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
1324→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1325→	ref, err := s.repo.Reference(refName, true)
1326→	if err != nil {
1327→		// Local branch doesn't exist, try remote-tracking branch
1328→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
1329→		ref, err = s.repo.Reference(remoteRefName, true)
1330→		if err != nil {
1331→			return nil, fmt.Errorf("sessions branch not found: %w", err)
1332→		}
1333→	}
1334→
1335→	commit, err := s.repo.CommitObject(ref.Hash())
1336→	if err != nil {
1337→		return nil, fmt.Errorf("failed to get commit object: %w", err)
1338→	}
1339→
1340→	tree, err := commit.Tree()
1341→	if err != nil {
1342→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
1343→	}
1344→
1345→	return tree, nil
1346→}
