1376→// copyMetadataDir copies all files from a directory to the checkpoint path.
1377→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
1378→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
1379→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
1380→		if err != nil {
1381→			return err
1382→		}
1383→
1384→		// Skip symlinks to prevent reading files outside the metadata directory.
1385→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
1386→		// then be captured in the checkpoint and stored in git history.
1387→		// NOTE: filepath.Walk uses os.Stat (follows symlinks), so info.Mode() never
1388→		// reports ModeSymlink. We use os.Lstat to check the entry itself.
1389→		// This check MUST come before IsDir() because Walk follows symlinked
1390→		// directories and would recurse into them otherwise.
1391→		linfo, lstatErr := os.Lstat(path)
1392→		if lstatErr != nil {
1393→			return fmt.Errorf("failed to lstat %s: %w", path, lstatErr)
1394→		}
1395→		if linfo.Mode()&os.ModeSymlink != 0 {
1396→			if info.IsDir() {
1397→				return filepath.SkipDir
1398→			}
1399→			return nil
1400→		}
1401→
1402→		if info.IsDir() {
1403→			return nil
1404→		}
1405→
1406→		// Get relative path within metadata dir
1407→		relPath, err := filepath.Rel(metadataDir, path)
1408→		if err != nil {
1409→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
1410→		}
1411→
1412→		// Prevent path traversal via symlinks pointing outside the metadata dir
1413→		if strings.HasPrefix(relPath, "..") {
1414→			return fmt.Errorf("path traversal detected: %s", relPath)
1415→		}
1416→
1417→		// Create blob from file with secrets redaction
1418→		blobHash, mode, err := createRedactedBlobFromFile(s.repo, path, relPath)
1419→		if err != nil {
1420→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
1421→		}
1422→
1423→		// Store at checkpoint path (use forward slashes for git tree compatibility on Windows)
1424→		fullPath := basePath + filepath.ToSlash(relPath)
1425→		entries[fullPath] = object.TreeEntry{
1426→			Name: fullPath,
1427→			Mode: mode,
1428→			Hash: blobHash,
1429→		}
1430→
1431→		return nil
1432→	})
1433→	if err != nil {
1434→		return fmt.Errorf("failed to walk metadata directory: %w", err)
1435→	}
1436→	return nil
1437→}
1438→
1439→// createRedactedBlobFromFile reads a file, applies secrets redaction, and creates a git blob.
1440→// JSONL files get JSONL-aware redaction; all other files get plain string redaction.
1441→func createRedactedBlobFromFile(repo *git.Repository, filePath, treePath string) (plumbing.Hash, filemode.FileMode, error) {
1442→	info, err := os.Stat(filePath)
1443→	if err != nil {
1444→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to stat file: %w", err)
1445→	}
1446→
1447→	mode := filemode.Regular
1448→	if info.Mode()&0o111 != 0 {
1449→		mode = filemode.Executable
1450→	}
1451→
1452→	content, err := os.ReadFile(filePath) //nolint:gosec // filePath comes from walking the metadata directory
1453→	if err != nil {
1454→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to read file: %w", err)
1455→	}
1456→
1457→	// Skip redaction for binary files — they can't contain text secrets and
1458→	// running string replacement on them would corrupt the data.
1459→	isBin, binErr := binary.IsBinary(bytes.NewReader(content))
1460→	if binErr != nil || isBin {
1461→		hash, err := CreateBlobFromContent(repo, content)
1462→		if err != nil {
1463→			return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1464→		}
1465→		return hash, mode, nil
1466→	}
1467→
1468→	if strings.HasSuffix(treePath, ".jsonl") {
1469→		redacted, jsonlErr := redact.JSONLBytes(content)
1470→		if jsonlErr != nil {
1471→			redacted = redact.Bytes(content)
1472→		}
1473→		content = redacted
1474→	} else {
1475→		content = redact.Bytes(content)
1476→	}
1477→
1478→	hash, err := CreateBlobFromContent(repo, content)
1479→	if err != nil {
1480→		return plumbing.ZeroHash, 0, fmt.Errorf("failed to create blob: %w", err)
1481→	}
1482→	return hash, mode, nil
1483→}
1484→
1485→// GetGitAuthorFromRepo retrieves the git user.name and user.email,
1486→// checking both the repository-local config and the global ~/.gitconfig.
1487→func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
1488→	// Get repository config (includes local settings)
1489→	cfg, err := repo.Config()
1490→	if err == nil {
1491→		name = cfg.User.Name
1492→		email = cfg.User.Email
1493→	}
1494→
1495→	// If not found in local config, try global config
1496→	if name == "" || email == "" {
1497→		globalCfg, err := config.LoadConfig(config.GlobalScope)
1498→		if err == nil {
1499→			if name == "" {
1500→				name = globalCfg.User.Name
1501→			}
1502→			if email == "" {
1503→				email = globalCfg.User.Email
1504→			}
1505→		}
1506→	}
1507→
1508→	// Provide sensible defaults if git user is not configured
1509→	if name == "" {
1510→		name = "Unknown"
1511→	}
1512→	if email == "" {
1513→		email = "unknown@local"
1514→	}
1515→
1516→	return name, email
1517→}
1518→
1519→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
1520→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
1521→// The agentType is used for reassembling chunks in the correct format.
1522→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
1523→	// Collect all transcript-related files
1524→	var chunkFiles []string
1525→	var hasBaseFile bool
1526→
1527→	for _, entry := range tree.Entries {
1528→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
1529→			hasBaseFile = true
1530→		}
1531→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
1532→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
1533→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
1534→			if idx > 0 {
1535→				chunkFiles = append(chunkFiles, entry.Name)
1536→			}
1537→		}
1538→	}
1539→
1540→	// If we have chunk files, read and reassemble them
1541→	if len(chunkFiles) > 0 {
1542→		// Sort chunk files by index
1543→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
1544→
1545→		// Check if base file should be included as chunk 0.
1546→		// NOTE: This assumes the chunking convention where the unsuffixed file
1547→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
1548→		if hasBaseFile {
1549→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
1550→		}
1551→
1552→		var chunks [][]byte
1553→		for _, chunkFile := range chunkFiles {
1554→			file, err := tree.File(chunkFile)
1555→			if err != nil {
1556→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
1557→					slog.String("chunk_file", chunkFile),
1558→					slog.String("error", err.Error()),
1559→				)
1560→				continue
1561→			}
1562→			content, err := file.Contents()
1563→			if err != nil {
1564→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
1565→					slog.String("chunk_file", chunkFile),
1566→					slog.String("error", err.Error()),
1567→				)
1568→				continue
1569→			}
1570→			chunks = append(chunks, []byte(content))
1571→		}
1572→
1573→		if len(chunks) > 0 {
1574→			result, err := agent.ReassembleTranscript(chunks, agentType)
1575→			if err != nil {
1576→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
1577→			}
1578→			return result, nil
1579→		}
1580→	}
1581→
1582→	// Fall back to reading base file (non-chunked or backwards compatibility)
1583→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
1584→		if content, err := file.Contents(); err == nil {
1585→			return []byte(content), nil
1586→		}
1587→	}
1588→
1589→	// Try legacy filename
1590→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
1591→		if content, err := file.Contents(); err == nil {
1592→			return []byte(content), nil
1593→		}
1594→	}
1595→
1596→	return nil, nil
1597→}
1598→
1599→// Author contains author information for a checkpoint.
1600→type Author struct {
1601→	Name  string
1602→	Email string
1603→}
1604→
1605→// GetCheckpointAuthor retrieves the author of a checkpoint from the entire/checkpoints/v1 commit history.
1606→// Returns the author of the commit that introduced this checkpoint's metadata.json file.
1607→// Returns empty Author if the checkpoint is not found or the sessions branch doesn't exist.
1608→func (s *GitStore) GetCheckpointAuthor(ctx context.Context, checkpointID id.CheckpointID) (Author, error) {
1609→	_ = ctx // Reserved for future use
1610→
1611→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1612→	ref, err := s.repo.Reference(refName, true)
1613→	if err != nil {
1614→		return Author{}, nil
1615→	}
1616→
1617→	// Path to the checkpoint's metadata file
1618→	metadataPath := checkpointID.Path() + "/" + paths.MetadataFileName
1619→
1620→	// Walk commit history looking for the commit that introduced this file
1621→	iter, err := s.repo.Log(&git.LogOptions{
1622→		From:  ref.Hash(),
1623→		Order: git.LogOrderCommitterTime,
1624→	})
1625→	if err != nil {
1626→		return Author{}, nil
1627→	}
1628→	defer iter.Close()
1629→
1630→	var author Author
1631→	var foundCommit *object.Commit
1632→
1633→	err = iter.ForEach(func(c *object.Commit) error {
1634→		tree, treeErr := c.Tree()
1635→		if treeErr != nil {
1636→			return nil //nolint:nilerr // Skip commits we can't read, continue searching
1637→		}
1638→
1639→		_, fileErr := tree.File(metadataPath)
1640→		if fileErr != nil {
1641→			// File doesn't exist in this commit - we've gone past the creation point
1642→			if foundCommit != nil {
1643→				return errStopIteration
1644→			}
1645→			return nil
1646→		}
1647→
1648→		// File exists - track it (oldest one with file is the creator)
1649→		foundCommit = c
1650→		author = Author{
1651→			Name:  c.Author.Name,
1652→			Email: c.Author.Email,
1653→		}
1654→		return nil
1655→	})
1656→
1657→	// Ignore errStopIteration - it's just for early exit
1658→	if err != nil && !errors.Is(err, errStopIteration) {
1659→		return Author{}, nil
1660→	}
1661→
1662→	return author, nil
1663→}
